-- Sankhuu: туршилтын (demo) 3 дэлгүүр, 18 бараа, 12 үнэлгээ. Supabase SQL Editor-т нэг удаа ажиллуулна.
-- Устгах бол demo-cleanup.sql. Бүх id 'demo_' угтвартай тул бодит өгөгдөлд хүрэхгүй.

BEGIN;
SET LOCAL search_path TO public;















-- Барааны үнэлгээний тоологчийг тооцно
UPDATE public."Product" p SET "ratingCount"=r.c, "ratingSum"=r.s FROM (SELECT "productId", count(*) c, sum(rating) s FROM "Review" WHERE id LIKE 'demo_%' GROUP BY 1) r WHERE p.id=r."productId";

COMMIT;
